<script setup>
import {ref,watch,onBeforeUnmount} from 'vue'
import {safeLink} from './contentSafety.js'
const props=defineProps({formId:String,preview:Object})
const config=ref(null),values=ref({}),consent=ref(false),website=ref(''),busy=ref(false),error=ref(''),result=ref(null),pending=ref(null),ready=ref(false)
let generation=0,timer
async function load(){const version=++generation;error.value='';clearTimeout(timer);ready.value=false
 try{let data=props.preview;if(!data){const r=await fetch('/api/forms/'+encodeURIComponent(props.formId),{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('Не удалось загрузить форму');data=await r.json()}if(version!==generation)return;config.value=data;values.value=Object.fromEntries((data.fields||[]).map(f=>[f.key,values.value[f.key]??(f.type==='checkbox'?false:'')]));if(!props.preview)timer=setTimeout(()=>ready.value=true,2100)}catch(e){if(version===generation)error.value=e.message}}
watch(()=>[props.formId,props.preview],load,{immediate:true})
onBeforeUnmount(()=>{generation++;clearTimeout(timer)})
async function submit(){if(props.preview||busy.value||!ready.value||result.value)return;busy.value=true;error.value=''
 if(!pending.value)pending.value={request_id:crypto.randomUUID(),values:JSON.parse(JSON.stringify(values.value)),consent:consent.value,website:website.value,challenge:config.value.challenge,source:location.pathname}
 try{const r=await fetch('/api/forms/'+encodeURIComponent(props.formId)+'/submit',{method:'POST',credentials:'omit',headers:{'content-type':'application/json','x-nova-form':'1'},body:JSON.stringify(pending.value),signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok){if(r.status>=400&&r.status<500){pending.value=null;if(r.status===409){await load()}}throw Error(data.error||'Не удалось отправить сообщение')}result.value=data;pending.value=null;values.value={};consent.value=false}catch(e){error.value=pending.value?'Не удалось подтвердить отправку. Нажмите «Проверить отправку»: обращение не продублируется.':e.message}finally{busy.value=false}}
</script>
<template><section class="nova-contact" :id="formId?'form-'+formId:undefined">
<p v-if="!config&&!error" role="status">Загрузка формы…</p><div v-if="result" class="nova-contact-success" role="status"><strong>{{result.message}}</strong><p v-if="result.number">Номер обращения: {{result.number}}</p></div>
<template v-else-if="config"><p v-if="!preview&&!config.available" role="status">Форма временно недоступна. Используйте другие контакты на сайте.</p><form v-else @submit.prevent="submit"><h2>{{config.title}}</h2><p v-if="config.description">{{config.description}}</p><fieldset :disabled="busy||!!pending||!!preview"><label v-for="field in config.fields" :key="field.key" :class="{'nova-contact-check':field.type==='checkbox'}"><template v-if="field.type==='checkbox'"><input v-model="values[field.key]" type="checkbox" :required="field.required">{{field.label}}{{field.required?' *':''}}</template><template v-else>{{field.label}}{{field.required?' *':''}}<textarea v-if="field.type==='textarea'" v-model="values[field.key]" rows="5" maxlength="3000" :required="field.required"></textarea><input v-else v-model="values[field.key]" :type="field.type" :maxlength="field.type==='tel'?40:field.type==='email'?254:3000" :required="field.required" :autocomplete="field.type==='email'?'email':field.type==='tel'?'tel':field.key==='name'?'name':'off'"></template></label><div class="nova-contact-honey" aria-hidden="true"><label>Ваш сайт<input v-model="website" type="text" tabindex="-1" autocomplete="off" maxlength="500"></label></div><label class="nova-contact-check"><input v-model="consent" type="checkbox" required><span>{{config.consent_label}} <a v-if="config.privacy_url&&safeLink(config.privacy_url)" :href="config.privacy_url" target="_blank" rel="noopener noreferrer">Подробнее</a></span></label></fieldset><p v-if="preview" class="nova-contact-small">Предпросмотр. Сообщения не отправляются.</p><button type="submit" :disabled="busy||!ready||!!preview">{{busy?'Отправляем…':pending?'Проверить отправку':config.button}}</button></form></template><p v-if="error" class="nova-contact-error" role="alert">{{error}}</p>
</section></template>
<style scoped>
.nova-contact{border:1px solid #d4dfd8;border-radius:var(--nova-radius,12px);padding:clamp(18px,4vw,36px);background:var(--nova-background,#fff);color:var(--nova-text,#203e30);min-width:0}.nova-contact h2{font-size:clamp(23px,4vw,32px);margin:0 0 14px;overflow-wrap:anywhere}.nova-contact p{font-size:14px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.nova-contact fieldset{border:0;padding:0;margin:22px 0;display:grid;gap:18px;min-width:0}.nova-contact label{font-size:14px;display:grid;gap:8px;overflow-wrap:anywhere}.nova-contact input,.nova-contact textarea{width:100%;font:inherit;padding:12px;border:1px solid #cbdad0;border-radius:8px;background:var(--nova-background,#fff);color:inherit;box-sizing:border-box}.nova-contact-check{display:flex!important;align-items:flex-start;gap:10px!important;line-height:1.6}.nova-contact-check input{width:auto;flex-shrink:0;margin-top:5px}.nova-contact-honey{position:absolute;left:-10000px;width:1px;height:1px;overflow:hidden}.nova-contact button{padding:14px 24px;background:var(--nova-primary,#286b4c);color:#fff;border:0;border-radius:var(--nova-radius,8px);font:inherit;cursor:pointer}.nova-contact button:disabled{opacity:.6;cursor:default}.nova-contact a{color:inherit}.nova-contact-error{padding:14px;background:#fff0ed;color:#982b29;border-radius:8px}.nova-contact-success{padding:20px;background:#eaf7ed;color:#24613b;border-radius:8px}.nova-contact-small{font-size:12px!important}
</style>
